<script setup lang="ts">
import { computed, ref, watch } from "vue";

import { uiText } from "@/i18n";
import { useChatStore } from "@/stores/chat";
import { useUiStore } from "@/stores/ui";

const chat = useChatStore();
const ui = useUiStore();
const elicitationJson = ref("{}");
const parseError = ref("");
const elicitationSchema = computed(() => JSON.stringify(chat.elicitation?.requested_schema || {}, null, 2));
watch(() => chat.elicitation?.interaction_id, () => { elicitationJson.value = "{}"; parseError.value = ""; });
function tr(chinese: string, english: string): string { return uiText(ui.language, chinese, english); }

async function acceptElicitation() {
  try {
    const value = JSON.parse(elicitationJson.value) as unknown;
    if (!value || Array.isArray(value) || typeof value !== "object") throw new Error(tr("响应必须是 JSON 对象", "Response must be a JSON object"));
    await chat.respondToElicitation("accept", value as Record<string, unknown>);
  } catch (error) { parseError.value = error instanceof Error ? error.message : tr("JSON 无效", "Invalid JSON"); }
}
</script>

<template>
  <div v-if="chat.confirmation" class="modal-backdrop">
    <section class="dialog-card"><span class="risk-pill">{{ chat.confirmation.risk_level || 'high' }}</span><h2>{{ tr('确认 Tool 操作', 'Confirm Tool action') }}</h2><dl><dt>Tool</dt><dd>{{ chat.confirmation.tool_name }}</dd><dt v-if="chat.confirmation.command_preview">{{ tr('命令预览', 'Command preview') }}</dt><dd v-if="chat.confirmation.command_preview"><code>{{ chat.confirmation.command_preview }}</code></dd></dl><p>{{ tr('仅批准本次已校验参数；修改后的参数仍需重新经过安全检查。', 'Approval applies only to these validated parameters; modified parameters require another safety review.') }}</p><div class="dialog-actions"><button @click="chat.decideConfirmation(false)">{{ tr('拒绝', 'Deny') }}</button><button class="danger-button" @click="chat.decideConfirmation(true)">{{ tr('仅批准一次', 'Approve once') }}</button></div></section>
  </div>
  <div v-if="chat.elicitation" class="modal-backdrop">
    <section class="dialog-card"><h2>{{ chat.elicitation.server_id ? `MCP · ${chat.elicitation.server_id}` : tr('MCP 请求输入', 'MCP input request') }}</h2><p>{{ chat.elicitation.message || tr('外部 MCP Server 请求结构化输入。', 'An external MCP Server requests structured input.') }}</p><a v-if="chat.elicitation.url" :href="chat.elicitation.url" target="_blank" rel="noreferrer">{{ tr('打开关联页面', 'Open related page') }}</a><details v-if="elicitationSchema !== '{}'" class="technical-details"><summary>{{ tr('请求 Schema', 'Request Schema') }}</summary><pre>{{ elicitationSchema }}</pre></details><label><span>{{ tr('JSON 响应', 'JSON response') }}</span><textarea v-model="elicitationJson" rows="7" /></label><p v-if="parseError" class="form-error">{{ parseError }}</p><div class="dialog-actions"><button @click="chat.respondToElicitation('cancel', null)">{{ tr('取消', 'Cancel') }}</button><button class="primary-button" @click="acceptElicitation">{{ tr('提交', 'Submit') }}</button></div></section>
  </div>
</template>
